machine_start_gcode:
; q2-offload start G-code (Happy Hare style)
SET_PRINT_STATS_INFO TOTAL_LAYER={total_layer_count}

PRINT_START BED=[bed_temperature_initial_layer_single] HOTEND=[nozzle_temperature_initial_layer] CHAMBER=[chamber_temperature] EXTRUDER=[initial_no_support_extruder]  INITIAL_TOOL={initial_tool} TOTAL_TOOLCHANGES=!total_toolchanges! REFERENCED_TOOLS=!referenced_tools! TOOL_COLORS=!colors! TOOL_TEMPS=!temperatures! TOOL_MATERIALS=!materials! FILAMENT_NAMES=!filament_names! PURGE_VOLUMES=!purge_volumes!

; Purge lines at the front of the bed (MMU load and bucket purge already done by PRINT_START)
M83        ; relative extrusion: Orca only sends M83 after this block
G92 E0
G4 P3000
G1 X108 Y1 F30000
G0 Z[initial_layer_print_height] F600
G0 X128 E8 F{outer_wall_volumetric_speed/(24/20) * 60}
G0 X133 E.3742 F{outer_wall_volumetric_speed/(0.3*0.5)/4 * 60}
G0 X138 E.3742 F{outer_wall_volumetric_speed/(0.3*0.5) * 60}
G0 X143 E.3742 F{outer_wall_volumetric_speed/(0.3*0.5)/4 * 60}
G0 X148 E.3742 F{outer_wall_volumetric_speed/(0.3*0.5) * 60}
G0 X153 E.3742 F{outer_wall_volumetric_speed/(0.3*0.5)/4  * 60}
G1 X154 Z-0.1
G1 X158
G1 Z1 F600
G1 X108 Y2.5 F30000
G0 Z[initial_layer_print_height] F600
G0 X128 E10 F{outer_wall_volumetric_speed/(24/20) * 60}
G0 X133 E.3742 F{outer_wall_volumetric_speed/(0.3*0.5)/4 * 60}
G0 X138 E.3742 F{outer_wall_volumetric_speed/(0.3*0.5) * 60}
G0 X143 E.3742 F{outer_wall_volumetric_speed/(0.3*0.5)/4 * 60}
G0 X148 E.3742 F{outer_wall_volumetric_speed/(0.3*0.5) * 60}
G0 X153 E.3742 F{outer_wall_volumetric_speed/(0.3*0.5)/4 * 60}
G1 X154 Z-0.1
G1 X158
G1 Z1 F600
